def format_bytes(n):
    """Return a human-readable size such as '1.5 KB' from a number of bytes.

    Args:
        n (int): Number of bytes.

    Returns:
        str: Human-readable size.
    """
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if n < 1024.0:
            return f"{n:.1f} {unit}".strip()
        n /= 1024.0
    return f"{n:.1f} PB"
